  "settings.acct.pc.sec.about.title": { en: "About You", pidgin: "About You", ha: "Game da Kai", ig: "Banyere Gị", yo: "Nípa Rẹ" },
  "settings.acct.pc.sec.about.why": { en: "Helps personalise your reports and will be needed to verify your identity when you upgrade to a paid plan.", pidgin: "E go make your reports fit you well, and we go need am to confirm who you be when you upgrade go paid plan.", ha: "Yana keɓance rahotannin ka, kuma za a buƙace shi don tabbatar da kai idan ka haɓaka zuwa tsarin biya.", ig: "Ọ na-eme ka akụkọ gị dabara gị, a ga-achọkwa ya iji kwado onye ị bụ mgbe ị kwalitere gaa na atụmatụ a na-akwụ ụgwọ.", yo: "Ó ń mú kí ìròyìn rẹ bá ọ mu, a ó sì nílò rẹ̀ láti jẹ́rìísí ẹni tí o jẹ́ nígbà tí o bá gbé sí ètò olówó." },
  "settings.acct.pc.sec.business.title": { en: "Your Business", pidgin: "Your Business", ha: "Kasuwancin Ka", ig: "Azụmaahịa Gị", yo: "Iṣẹ́ Òwò Rẹ" },
  "settings.acct.pc.sec.business.why": { en: "Makes your analytics and reports more accurate, and surfaces the right insights for your industry.", pidgin: "E go make your analytics and reports correct pass, and show you the right insights for your line of business.", ha: "Yana sa bincike da rahotannin ka su fi daidai, kuma yana nuna maka shawarwarin da suka dace da sana'ar ka.", ig: "Ọ na-eme ka nyocha na akụkọ gị ziri ezi karịa, ma gosi gị ndụmọdụ kwesịrị ụdị azụmaahịa gị.", yo: "Ó ń mú kí àyẹ̀wò àti ìròyìn rẹ péye sí i, ó sì ń fi ìmọ̀ràn tó yẹ iṣẹ́ rẹ hàn ọ́." },
  "settings.acct.pc.sec.location.title": { en: "Location", pidgin: "Location", ha: "Wuri", ig: "Ebe", yo: "Ibùdó" },
  "settings.acct.pc.sec.location.why": { en: "Your business address appears on invoices and is used for local insights.", pidgin: "Your business address go show for invoices and we dey use am for local insights.", ha: "Adireshin kasuwancin ka yana bayyana a kan takardun biya kuma ana amfani da shi don shawarwarin yanki.", ig: "Adreesị azụmaahịa gị na-apụta n'akwụkwọ ụgwọ, a na-ejikwa ya maka ndụmọdụ mpaghara.", yo: "Àdírẹ́sì iṣẹ́ rẹ máa ń hàn lórí ìwé owó, a sì ń lò ó fún ìmọ̀ràn àdúgbò." },
  "settings.acct.pc.sec.verification.title": { en: "Verification", pidgin: "Verification", ha: "Tantancewa", ig: "Nkwenye", yo: "Ìjẹ́rìísí" },
  "settings.acct.pc.sec.verification.why": { en: "A business document earns a verified badge, builds client trust, and is required when upgrading to a paid plan.", pidgin: "Business document go give you verified badge, make customers trust you, and you go need am to upgrade go paid plan.", ha: "Takardar kasuwanci tana ba ka alamar tantancewa, tana gina amincewar abokan ciniki, kuma ana buƙatar ta idan za ka haɓaka zuwa tsarin biya.", ig: "Akwụkwọ azụmaahịa na-enweta gị akara nkwenye, na-eme ka ndị ahịa tụkwasị gị obi, a na-achọkwa ya mgbe ị na-akwalite gaa na atụmatụ a na-akwụ ụgwọ.", yo: "Ìwé iṣẹ́ òwò máa ń fún ọ ní àmì ìjẹ́rìísí, ó ń mú kí oníbàárà fọkàn tán ọ, a sì nílò rẹ̀ láti gbé sí ètò olówó." },
