  "settings.acct.pc.takePhoto": { en: "Take or choose a photo", pidgin: "Snap or choose photo", ha: "Ɗauki ko zaɓi hoto", ig: "See ma ọ bụ họrọ foto", yo: "Ya tàbí yan fọ́tò" },
  "settings.acct.pc.docOnFile": { en: "✓ Document already on file", pidgin: "✓ Document don dey already", ha: "✓ Takarda tana nan riga", ig: "✓ Akwụkwọ adịlarị", yo: "✓ Ìwé ti wà nílẹ̀ tẹ́lẹ̀" },
  "settings.acct.pc.opensCamera": { en: "Opens your camera or gallery", pidgin: "E go open your camera or gallery", ha: "Yana buɗe kyamara ko hotunan ka", ig: "Ọ na-emepe igwefoto ma ọ bụ ebe foto gị", yo: "Ó ń ṣí kámẹ́rà tàbí àkójọ fọ́tò rẹ" },
  "settings.acct.pc.unsavedConfirm": { en: "You have changes you haven't saved. Close and lose them?", pidgin: "You get changes wey you never save. Close am make dem lost?", ha: "Akwai canje-canjen da ba ka ajiye ba. Ka rufe ka rasa su?", ig: "Ị nwere mgbanwe ị chekwabeghị. Mechie ma tufuo ha?", yo: "O ní àwọn àyípadà tí o kò tíì fipamọ́. Ṣé kí o pa á dé kí wọ́n sọnù?" },
  "settings.acct.pc.ninError": { en: "Your NIN must be exactly 11 digits — or leave it empty for now.", pidgin: "Your NIN must be exactly 11 numbers — or leave am empty for now.", ha: "Dole NIN ɗin ka ya zama lambobi 11 daidai — ko ka bar shi babu komai yanzu.", ig: "NIN gị ga-abụrịrị ọnụọgụ 11 kpọmkwem — ma ọ bụ hapụ ya efu ugbu a.", yo: "NIN rẹ gbọ́dọ̀ jẹ́ nọ́ńbà 11 gẹ́lẹ́ — tàbí fi í sílẹ̀ ní òfo fún báyìí." },
  "settings.acct.pc.uploadingLogo": { en: "Uploading logo…", pidgin: "E dey upload logo…", ha: "Ana ɗora tambari…", ig: "Ọ na-ebulite akara…", yo: "Ó ń gbé àmì sókè…" },
  "settings.acct.pc.docTypeError": { en: "Please choose a photo (JPG or PNG) of your document.", pidgin: "Abeg choose photo (JPG or PNG) of your document.", ha: "Don Allah zaɓi hoton (JPG ko PNG) takardar ka.", ig: "Biko họrọ foto (JPG ma ọ bụ PNG) nke akwụkwọ gị.", yo: "Jọ̀wọ́ yan fọ́tò (JPG tàbí PNG) ìwé rẹ." },
  "settings.acct.pc.uploadingDoc": { en: "Uploading document…", pidgin: "E dey upload document…", ha: "Ana ɗora takarda…", ig: "Ọ na-ebulite akwụkwọ…", yo: "Ó ń gbé ìwé sókè…" },
  "settings.acct.pc.saveFailed": { en: "Could not save. Please try again.", pidgin: "E no fit save. Abeg try again.", ha: "Ba a iya ajiyewa ba. Don Allah sake gwadawa.", ig: "Enweghị ike ichekwa. Biko nwaa ọzọ.", yo: "A kò lè fipamọ́. Jọ̀wọ́ gbìyànjú lẹ́ẹ̀kan sí i." },
  "settings.acct.pc.saveFailedConn": { en: "Could not save. Please check your connection and try again.", pidgin: "E no fit save. Abeg check your network and try again.", ha: "Ba a iya ajiyewa ba. Don Allah duba haɗin intanet ɗin ka ka sake gwadawa.", ig: "Enweghị ike ichekwa. Biko lelee njikọ gị ma nwaa ọzọ.", yo: "A kò lè fipamọ́. Jọ̀wọ́ ṣàyẹ̀wò ìsopọ̀ rẹ kí o sì gbìyànjú lẹ́ẹ̀kan sí i." },
  "settings.acct.pc.pctComplete": { en: "{pct}% complete", pidgin: "{pct}% complete", ha: "An kammala {pct}%", ig: "Emezuola {pct}%", yo: "Ó ti parí {pct}%" },
  "settings.acct.pc.stepOf": { en: "Step {n} of {total} · {title}", pidgin: "Step {n} of {total} · {title}", ha: "Mataki {n} cikin {total} · {title}", ig: "Nzọụkwụ {n} n'ime {total} · {title}", yo: "Ìgbésẹ̀ {n} nínú {total} · {title}" },
