  "settings.acct.pc.complete": { en: "Your profile is complete", pidgin: "Your profile don complete", ha: "Bayanan ka sun cika", ig: "Profaịlụ gị zuru ezu", yo: "Profaili rẹ ti pé" },
  "settings.acct.pc.saved": { en: "Saved", pidgin: "E don save", ha: "An ajiye", ig: "Echekwara", yo: "A ti fipamọ́" },
  "settings.acct.pc.completeBody": { en: "Thanks — your reports, invoices and insights now use your full business details.", pidgin: "Thank you — your reports, invoices and insights don dey use all your business details now.", ha: "Na gode — rahotanni, takardun biya da shawarwarin ka yanzu suna amfani da cikakkun bayanan kasuwancin ka.", ig: "Daalụ — akụkọ, akwụkwọ ụgwọ na ndụmọdụ gị na-eji nkọwa azụmaahịa gị zuru ezu ugbu a.", yo: "Ẹ ṣé — ìròyìn, ìwé owó àti ìmọ̀ràn rẹ ti ń lo gbogbo àlàyé iṣẹ́ òwò rẹ báyìí." },
  "settings.acct.pc.partialBody": { en: "Your profile is {pct}% complete. Tap a step above any time to finish the rest.", pidgin: "Your profile don complete {pct}%. Tap any step for up anytime to finish the rest.", ha: "An kammala bayanan ka {pct}%. Matsa wani mataki a sama kowane lokaci don kammala sauran.", ig: "Profaịlụ gị emezuola {pct}%. Pịa nzọụkwụ dị n'elu oge ọ bụla iji mezue ndị fọdụrụ.", yo: "Profaili rẹ ti parí {pct}%. Tẹ ìgbésẹ̀ kan lókè nígbàkígbà láti parí èyí tó kù." },
