  "settings.acct.pc.filledOf": { en: "{filled} of {total} filled", pidgin: "{filled} of {total} don fill", ha: "An cike {filled} cikin {total}", ig: "Ejupụtala {filled} n'ime {total}", yo: "A ti kún {filled} nínú {total}" },
  "settings.acct.pc.optionalNote": { en: "Every field is optional — fill what you can and continue.", pidgin: "You no must fill everything — fill wetin you fit and continue.", ha: "Kowane fili zaɓi ne — cike abin da za ka iya ka ci gaba.", ig: "Ọ dịghị mpaghara ọ bụla a manyere — dejupụta ihe ị nwere ike ma gaa n'ihu.", yo: "Kò pọn dandan láti kún gbogbo rẹ̀ — kún èyí tí o bá lè ṣe kí o sì tẹ̀síwájú." },
  "settings.acct.pc.saveFinish": { en: "Save & finish", pidgin: "Save & finish", ha: "Ajiye & gama", ig: "Chekwaa & mechie", yo: "Fipamọ́ & parí" },
  "settings.acct.pc.saveContinue": { en: "Save & continue", pidgin: "Save & continue", ha: "Ajiye & ci gaba", ig: "Chekwaa & gaa n'ihu", yo: "Fipamọ́ & tẹ̀síwájú" },
