  "settings.acct.pe.invalidEmail": { en: "Enter a valid email address", pidgin: "Put correct email address", ha: "Shigar da ingantaccen adireshin imel", ig: "Tinye adreesị email ziri ezi", yo: "Tẹ àdírẹ́sì imeeli tó tọ́" },
  "settings.acct.pe.enterCode": { en: "Enter the 6-digit code from your email", pidgin: "Put the 6-digit code wey dey your email", ha: "Shigar da lambar lamba 6 daga imel ɗin ka", ig: "Tinye koodu ọnụọgụ 6 sitere n'email gị", yo: "Tẹ kóòdù oní-nọ́ńbà 6 láti inú imeeli rẹ" },
