  "settings.notif.center.emptyBody": { en: "Notifications for sales, savings, stock, and more will appear here.", pidgin: "Notifications for sales, savings, stock, and more go show here.", ha: "Sanarwa game da tallace-tallace, ajiya, kaya, da sauransu za su bayyana a nan.", ig: "Ọkwa maka ire ahịa, nchekwa ego, ngwa ahịa, na ndị ọzọ ga-apụta ebe a.", yo: "Ìwífún nípa títà, ìfowópamọ́, ọjà, àti àwọn míì yóò hàn níbí." },
