  "settings.kyc.legal.agreeContinue": { en: "Agree and Continue", pidgin: "Agree and Continue", ha: "Amince kuma Ci Gaba", ig: "Kwenye ma Gaa n'Ihu", yo: "Gbà kí o sì Tẹ̀síwájú" },
  "settings.kyc.legal.mustAccept": { en: "You must accept both documents to use KudiAI", pidgin: "You must accept the two documents to use KudiAI", ha: "Dole ne ka amince da takardun biyu don amfani da KudiAI", ig: "Ị ga-ekwerịrị akwụkwọ abụọ ahụ iji jiri KudiAI", yo: "O gbọ́dọ̀ gba àwọn ìwé méjèèjì láti lo KudiAI" },
